configuration.script:
// Berechnet die Ladezyklen (Vollzyklen) des Akkus.
// Grundlage: Register 35209 = vom Wechselrichter gezaehlte Gesamtentladung
// seit Installation, in 0,1 kWh (nicht vom BMS).
// Vollzyklen = Gesamtentladung (kWh) / nutzbare Kapazitaet (kWh)
//
// Nutzbare Kapazitaet: Pylontech Force H1 mit 6 Modulen = 20,24 kWh
// (Datenblatt: 6M nominal 21,31 kWh, nutzbar 20,24 kWh).
// Bei Erweiterung um Module diesen Wert anpassen.
val kapazitaetKWh = 20.24

if (Goodwe_Batt_Entladung_Raw.state instanceof Number) {
    val entladungKWh = (Goodwe_Batt_Entladung_Raw.state as Number).doubleValue / 10.0
    Akku_Entladung_Gesamt.postUpdate(entladungKWh)
    Akku_Ladezyklen.postUpdate(entladungKWh / kapazitaetKWh)
}

// Schaltet den GoodWe-Wechselrichter zwischen Netzladen und Automatik um.
// Entspricht:
//   EIN: 47512 = 3000 W, danach 47511 = 2 (Laden)
//   AUS: 47511 = 1 (Automatik), danach 47512 = 0
// Der Schalter selbst wird NICHT hier gesetzt, sondern nur durch die Regel
// "Netzladen Status", die den tatsaechlich gelesenen Modus anzeigt.
val ladeleistung = 3000

if (receivedCommand == ON) {
    Goodwe_EMS_Power.sendCommand(ladeleistung)
    Thread::sleep(300)
    Goodwe_EMS_Mode.sendCommand(2)
    logInfo("Netzladen", "Netzladen EIN angefordert: Mode 2, " + ladeleistung + " W")
} else {
    Goodwe_EMS_Mode.sendCommand(1)
    Thread::sleep(300)
    Goodwe_EMS_Power.sendCommand(0)
    logInfo("Netzladen", "Netzladen AUS angefordert: Mode 1 (Automatik), 0 W")
}

// Zeigt im Schalter immer den tatsaechlichen Zustand des Wechselrichters an.
// Register 47511 wird alle 2 Sekunden gelesen. Steht es auf 2 (Laden),
// ist der Schalter AN, sonst AUS - unabhaengig davon, was zuletzt geklickt wurde.
if (Goodwe_EMS_Mode.state instanceof Number) {
    val soll = if ((Goodwe_EMS_Mode.state as Number).intValue == 2) ON else OFF
    if (Goodwe_Netzladen.state != soll) {
        Goodwe_Netzladen.postUpdate(soll)
        logInfo("Netzladen", "Status vom Wechselrichter: EMS Mode " + Goodwe_EMS_Mode.state + " -> Schalter " + soll)
    }
}

// Arbeitszahl heute (Tages-COP) der Vitocal 250-A:
// erzeugte Waerme heute / aufgenommener Strom heute, jeweils Heizen + Warmwasser.
// Grundlage sind die Tageszaehler der Viessmann-API (heat.production.summary und
// power.consumption.summary). Sie beginnen um Mitternacht wieder bei 0. Solange
// weniger als 0,1 kWh Strom gezaehlt sind, bleibt der Wert leer (sonst springt er wild).
var double strom = 0.0
var double waerme = 0.0
if (WP_Strom_Heizen_Heute.state instanceof Number) strom = strom + (WP_Strom_Heizen_Heute.state as Number).doubleValue
if (WP_Strom_Warmwasser_Heute.state instanceof Number) strom = strom + (WP_Strom_Warmwasser_Heute.state as Number).doubleValue
if (WP_Waerme_Heizen_Heute.state instanceof Number) waerme = waerme + (WP_Waerme_Heizen_Heute.state as Number).doubleValue
if (WP_Waerme_Warmwasser_Heute.state instanceof Number) waerme = waerme + (WP_Waerme_Warmwasser_Heute.state as Number).doubleValue

if (strom >= 0.1) {
    WP_COP_Heute.postUpdate(waerme / strom)
} else {
    WP_COP_Heute.postUpdate(NULL)
}

// PV-Ueberschuss in den Warmwasserspeicher (und damit in den Puffer) schieben.
// Laeuft jede Minute. Die Erhoehung startet, wenn ALLE Bedingungen erfuellt sind:
//   - Freigabe WP_PV_Boost_Freigabe ist AN
//   - Heizkreispumpe Fussboden (WP_HK2_Pumpe) ist AN
//   - Akkustand > 95 %
//   - jetzt ist mehr als 2 Stunden vor Sonnenuntergang (Astro-Thing Frankfurt)
//   - PV-Leistung (Strang 1 + 2) im Mittel der letzten 5 Minuten > 1000 W
//   - heute gab es noch keine Erhoehung ODER das Warmwasser (WP_Warmwasser_Ist) ist
//     seitdem unter 50 °C gefallen; Warmwasser Soll liegt unter 59 °C
// Dann: Warmwasser Soll fuer 60 Minuten auf 59 °C, danach zurueck auf den alten Wert.
// Hat jemand den Sollwert in der Zwischenzeit von Hand geaendert, bleibt dieser Wert stehen.
val zielTemp = 59
val akkuMin = 95.0
val pvMin = 1000.0
val pvMinuten = 5
val dauerMinuten = 60
val stundenVorSonnenuntergang = 2
val nachladenUnter = 50.0

// 1) Laufende Erhoehung: nach Ablauf den alten Sollwert wiederherstellen.
//    Ist das Ende unbekannt (z. B. nach einem Neustart), wird sofort zurueckgesetzt.
if (WP_PV_Boost.state == ON) {
    if (WP_PV_Boost_Ende.state instanceof DateTimeType
        && now.toInstant.isBefore((WP_PV_Boost_Ende.state as DateTimeType).instant)) return;

    val vorher = WP_PV_Boost_Soll_Vorher.state
    val aktuell = WP_Warmwasser_Soll.state
    if (vorher instanceof Number && aktuell instanceof Number
        && Math.abs((aktuell as Number).doubleValue - zielTemp) < 0.5) {
        WP_Warmwasser_Soll.sendCommand(vorher.toString)
        logInfo("PV-Warmwasser", "Erhoehung beendet, Warmwasser Soll zurueck auf " + vorher)
    } else {
        logInfo("PV-Warmwasser", "Erhoehung beendet, Warmwasser Soll (" + aktuell + ") wurde zwischenzeitlich geaendert und bleibt")
    }
    WP_PV_Boost.postUpdate(OFF)
    return;
}

// 2) Bedingungen fuer den Start pruefen (guenstige Pruefungen zuerst, Persistence zuletzt)
if (WP_PV_Boost_Freigabe.state != ON) return;
if (WP_HK2_Pumpe.state != ON) return;
if (!(Akkustand.state instanceof Number) || (Akkustand.state as Number).doubleValue <= akkuMin) return;

if (!(Sonnenuntergang.state instanceof DateTimeType)) return;
val spaetestens = (Sonnenuntergang.state as DateTimeType).instant.minusSeconds(stundenVorSonnenuntergang * 3600)
if (!now.toInstant.isBefore(spaetestens)) return;

// Heute schon erhoeht? Dann nur erneut, wenn das Warmwasser unter 50 °C gefallen ist.
val heuteBeginn = now.toLocalDate.atStartOfDay(now.zone).toInstant
if (WP_PV_Boost_Ende.state instanceof DateTimeType
    && (WP_PV_Boost_Ende.state as DateTimeType).instant.isAfter(heuteBeginn)) {
    val ist = WP_Warmwasser_Ist.state
    if (!(ist instanceof Number) || (ist as Number).doubleValue >= nachladenUnter) return;
}

val sollAlt = WP_Warmwasser_Soll.state
if (!(sollAlt instanceof Number) || (sollAlt as Number).doubleValue >= zielTemp) return;

val seit = now.minusMinutes(pvMinuten)
val pv1 = Goodwe_PV1_Power.averageSince(seit)
val pv2 = Goodwe_PV2_Power.averageSince(seit)
if (!(pv1 instanceof Number) || !(pv2 instanceof Number)) return;
val pvMittel = (pv1 as Number).doubleValue + (pv2 as Number).doubleValue
if (pvMittel <= pvMin) return;

// 3) Erhoehung starten
WP_PV_Boost_Soll_Vorher.postUpdate(sollAlt)
WP_PV_Boost_Ende.postUpdate(new DateTimeType(now.plusMinutes(dauerMinuten)))
WP_PV_Boost.postUpdate(ON)
WP_Warmwasser_Soll.sendCommand(zielTemp + " °C")
logInfo("PV-Warmwasser", "Erhoehung gestartet: Warmwasser Soll " + sollAlt + " -> " + zielTemp
     + " °C fuer " + dauerMinuten + " min (Warmwasser " + WP_Warmwasser_Ist.state + ", Akku " + Akkustand.state + " %, PV-Mittel "
    + Math.round(pvMittel) + " W)")

// Ohne gespeicherten Zustand (erste Inbetriebnahme) ist die PV-Warmwasser-Automatik eingeschaltet.
// Eine laufende Erhoehung beendet die Regel "Waermepumpe PV-Warmwasser" beim naechsten Durchlauf
// selbst, wenn das Ende nach dem Neustart nicht mehr bekannt ist.
if (WP_PV_Boost_Freigabe.state == NULL || WP_PV_Boost_Freigabe.state == UNDEF) {
    WP_PV_Boost_Freigabe.postUpdate(ON)
}
if (WP_PV_Boost.state == NULL || WP_PV_Boost.state == UNDEF) {
    WP_PV_Boost.postUpdate(OFF)
}

// Status der elektrischen Zusatzheizung (Heizstab) der Vitocal 250-A.
// Das API-Feld heating.heatingRod "active" meldet nur, ob der Heizstab freigegeben ist,
// nicht ob er gerade heizt. Der Status wird deshalb aus den Zaehlern abgeleitet:
// Steigt der Tagesverbrauch des Heizstabs (Heizen oder Warmwasser) oder seine Startzahl,
// heizt er -> AN. Kommt 15 Minuten lang kein Anstieg mehr -> AUS.
// Um Mitternacht fallen die Tageszaehler auf 0, das wird ignoriert.
if (!(previousState instanceof Number) || !(newState instanceof Number)) return;
if ((newState as Number).doubleValue <= (previousState as Number).doubleValue) return;

WP_Zusatzheizung.postUpdate(ON)
val alterTimer = privateCache.get("ausTimer") as Timer
alterTimer?.cancel()
privateCache.put("ausTimer", createTimer(now.plusMinutes(15), [ |
    WP_Zusatzheizung.postUpdate(OFF)
]))

// Nach einem Neustart laeuft kein Abschalt-Timer. Damit ein wiederhergestellter
// Zustand AN nicht haengen bleibt, beginnt die Anzeige mit AUS.
WP_Zusatzheizung.postUpdate(OFF)
